["[]E_KIND","built-in","Event -> Char","Event -> Char","","builtins.html#-5b-5dE_KIND","What kind an event is, as text: `tick`, `down`, `move`, `up`, `click`, `key`, `choose` (a choice in the host's controls, `[]E_AT` giving which list and which item) or `end`."],
["[]E_AT","built-in","Event -> Float","Event -> Float","","builtins.html#-5b-5dE_AT","An event's numbers: `x y` for a pointer, the seconds since the last tick for a tick, the list and the item for a choice, none for a key or the end."],
["[]E_KEY","built-in","Event -> Key","Event -> Key","","builtins.html#-5b-5dE_KEY","A key event's key (`[]K_CHAR` reads its character); an error for the other kinds."],
["[]C_OLOR","built-in","Int -> Color","Int -> Color","","builtins.html#-5b-5dC_OLOR","Color n (1 to 8: black, red, green, yellow, blue, magenta, cyan, white), for the Terminal library, which names them (`t:RED`)."],
["[]F_G","built-in","Color -> Char -> Char","Color -> Char -> Char","","builtins.html#-5b-5dF_G","Text in a foreground color: the text wrapped in the codes a terminal (or the live demo's grid) colors it with; print it to see it."],
["[]B_G","built-in","Color -> Char -> Char","Color -> Char -> Char","","builtins.html#-5b-5dB_G","Text on a background color, as []F_G does the foreground."],
["[]B_OLD","built-in","Char -> Char","Char -> Char","","builtins.html#-5b-5dB_OLD","Text in bold (wrapped in its codes, as []F_G)."],
["[]A_T","built-in","Int -> Char -> Char","Int -> Char -> Char","","builtins.html#-5b-5dA_T","Text placed at a row and a column (1-origin), for a program that draws a screen: the code moving the cursor there, then the text."],
["[]C_LS","built-in","Unit -> Char","Unit -> Char","","builtins.html#-5b-5dC_LS","The text that clears the screen and moves the cursor home; print it."],
["f_ormat","built-in","a -> Char","a -> Char","","builtins.html#f_ormat","A value as the text it prints as."],
["n_umbers","built-in","Char -> Float","Char -> Float","","builtins.html#n_umbers","The numbers in a text, as Floats."],
["[]R_EJECT","built-in","Char -> Char -> Char","Char -> Char -> Char","","builtins.html#-5b-5dR_EJECT","Fail the macro call being expanded: the left text is a code and where to report it (call, left or right), the right text the message."],
["[]S_TATEMENT","built-in","Truthy a => Unit -> a","Unit -> a","","builtins.html#-5b-5dS_TATEMENT","Whether the call being expanded stands as a statement of its own."],
["[]F_ILE","built-in","Unit -> Char","Unit -> Char","","builtins.html#-5b-5dF_ILE","The file the call being expanded is written in (`@ f_ile\u003c @`)."],
["[]L_INE","built-in","Unit -> Int","Unit -> Int","","builtins.html#-5b-5dL_INE","The line the call being expanded is written on (`@ l_ine\u003c @`)."],
["[]I_NCLUDE","built-in","Char -> Char","Char -> Char","","builtins.html#-5b-5dI_NCLUDE","The text of a file, by a path relative to the file the call being expanded is written in (`@ i_nclude\u003c \"data.txt\"`)."],
["[]C_FG","built-in","Truthy a => Char -> a","Char -> a","","builtins.html#-5b-5dC_FG","Whether a configuration fact holds: the platform (cli or web) or a flag set with `xetal --cfg NAME` (`@ c_fg\u003c \"web\"`)."],
["[]G_RID","built-in","Eq a => a -> Char","a -> Char","","builtins.html#-5b-5dG_RID","An array as a picture, returned as SVG text: a vector as one row of cells, a matrix as a grid, a rank-3 array as frames shown in turn."],
["[]P_ATH","built-in","Num a => a -> Char","a -> Char","","builtins.html#-5b-5dP_ATH","Points as a picture, returned as SVG text: 2 rows, x over y, joined in order and fitted into a 400-pixel picture with y pointing up; a rank-3 array is frames of paths shown in turn."],
["[]S_HOW","built-in","Char -> Char","Char -> Char","","builtins.html#-5b-5dS_HOW","Show a picture, and return it: the command line writes it to a numbered file (`--draw DIR`, else `XETAL_DRAW`, else the current directory), the browser shows it beside the program."],
["s_hape","built-in","a -> Int","a -> Int","","builtins.html#s_hape","The length of each axis."],
["t_ally","built-in","a -> Int","a -> Int","","builtins.html#t_ally","How many items along the first axis: the rows of a matrix."],
["r_ange","built-in","Int -> Int","Int -> Int","","builtins.html#r_ange","The numbers 1 to n."],
["o_ffsets","built-in","Int -> Int","Int -> Int","","builtins.html#o_ffsets","The numbers 0 to n - 1."],
["f_irst","built-in","a -> a","a -> a","","builtins.html#f_irst","The first item along the first axis: the first row."],
["r_avel","built-in","a -> a","a -> a","","builtins.html#r_avel","Every item as one vector, row after row."],
["r_eshape","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#r_eshape","The items of the right argument, taken in order and repeated as needed, into the shape on the left."],
["t_ake","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#t_ake","The first n items (the last n for a negative n) along the first axis, or along the subscript's axis."],
["d_rop","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#d_rop","All but the first n items (the last n for a negative n), along the first axis or the subscript's."],
["s_elect","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#s_elect","The items at the given positions (from 1) along the first axis, or along the subscript's axis."],
["r_eplicate","built-in","Truthy a => a -> b -> b","a -> b -> b","","builtins.html#r_eplicate","Replicate: each item (each row of a matrix) repeated as many times as its count on the left, so a 0 drops it and a mask of 1s and 0s keeps the items where it is 1; one count extends to every item, and with a subscript the counts go along that axis."],
["c_at","built-in","a -> a -> a","a -> a -> a","","builtins.html#c_at","Join along the first axis, or with a subscript along that axis of both arguments: `c_at_2` puts matrices side by side."],
["r_/","built-in","(a -> a -> a) -> a -> a","( a -> a -> a ) -> a -> a","","builtins.html#r_-2f","Reduce: combine the items along the first axis with the function, from the right (`'- r_/ 1 2 3` is 1 - (2 - 3))."],
["s_\\","built-in","(a -> a -> a) -> a -> a","( a -> a -> a ) -> a -> a","","builtins.html#s_-5c","Scan: every running reduce, the last being the whole reduce."],
["e_ach","built-in","(a -> b) -> a -> b","( a -> b ) -> a -> b","","builtins.html#e_ach","Apply a function to every item."],
["m_ap","built-in","(a -> b) -> a -> Box b","( a -> b ) -> a -> Box b","","builtins.html#m_ap","Map: the function on each item, every result boxed, so the function may give an array (e_ach wants one value per item)."],
["t_able","built-in","(a -> b -> c) -> a -> b -> c","( a -> b -> c ) -> a -> b -> c","","builtins.html#t_able","Every pairing of an item on the left with one on the right (APL's outer product): the result has both shapes."],
["i_nner","built-in","(a -> b -> c) -> (c -> c -> c) -> a -> b -> c","( a -> b -> c ) -> ( c -> c -> c ) -> a -> b -> c","","builtins.html#i_nner","Inner product: `A '+ '* i_nner B` is matrix multiplication (the last axis of A with the first of B)."],
["c_ompose","built-in","(Any a, Any b, Any c) => (a -> b) -> (b -> c) -> a -> c","( a -> b ) -> ( b -> c ) -> a -> c","","builtins.html#c_ompose","`'f 'g c_ompose x` is f applied to g applied to x; the atop train `[f g] x` is the same."],
["s_wap","built-in","(Any a, Any b, Any c) => (a -> b -> c) -> b -> a -> c","( a -> b -> c ) -> b -> a -> c","","builtins.html#s_wap","`x 'f s_wap y` is `y f x`: the arguments swapped."],
["p_ower","built-in","Any a => (a -> a) -> Int -> a -> a","( a -> a ) -> Int -> a -> a","","builtins.html#p_ower","`n 'f p_ower x` applies f to x n times; `f_^n` is the same with a literal count."],
["i_ndexOf","built-in","Eq a => a -> a -> Int","a -> a -> Int","","builtins.html#i_ndexOf","Where each item of the right argument is first found among the items of the left, from 1; one past the end when it is not there."],
["m_ember?","built-in","(Eq a, Truthy b) => a -> a -> b","a -> a -> b","","builtins.html#m_ember-3f","Whether each item of the left is among the items of the right."],
["m_atch","built-in","(Match a, Truthy b) => a -> a -> b","a -> a -> b","","builtins.html#m_atch","Whether both sides have the same shape and equal items (APL's match): one result for the whole arrays, where `=` compares item by item."],
["u_nique","built-in","Eq a => a -> a","a -> a","","builtins.html#u_nique","The items without repeats, in first-seen order."],
["s_ort","built-in","Ord a => a -> a","a -> a","","builtins.html#s_ort","The items in ascending order (the rows of a matrix, compared in order); with a subscript, sorted along that axis."],
["g_rade","built-in","Ord a => a -> Int","a -> Int","","builtins.html#g_rade","The positions that would sort the items: `(g_rade v) s_elect v` is `s_ort v`."],
["w_here","built-in","Truthy a => a -> Int","a -> Int","","builtins.html#w_here","The positions of the 1s in a vector."],
["e_nclose","built-in","a -> Box a","a -> Box a","","builtins.html#e_nclose","Enclose: the whole value as one item, a box, so arrays can be items of other arrays; a strand of strings encloses each string."],
["d_isclose","built-in","Box a -> a","Box a -> a","","builtins.html#d_isclose","Disclose: what a box holds."],
["d_isplay","built-in","a -> Char","a -> Char","","builtins.html#d_isplay","Display: any value as APL2's DISPLAY draws it, as a character matrix, flat arrays framed too: an arrow along the top, a down arrow for each leading axis, and a mark at the bottom for what it holds (`~` numbers, a plain line characters, `e` boxes); a simple scalar is itself."],
["p_artition","built-in","Truthy a => a -> b -> Box b","a -> b -> Box b","","builtins.html#p_artition","Partition: the items (rows of a matrix) cut into pieces by the keys on the left, one per item: a new piece starts where the key goes up, and an item with key 0 is left out, so a mask of 1s and 0s cuts out the runs of 1s."],
["e_ncode","built-in","Int -> Int -> Int","Int -> Int -> Int","","builtins.html#e_ncode","Encode: the digits of a number in the radix on the left, most significant first (APL's encode)."],
["d_ecode","built-in","Num a => a -> a -> a","a -> a -> a","","builtins.html#d_ecode","Decode: the number whose digits, in the radix on the left, are on the right (APL's decode), the inverse of `e_ncode`."],
["r_ev","built-in","a -> a","a -> a","","builtins.html#r_ev","Reverse the order of the items along the first axis (the rows of a matrix), or along the subscript's axis."],
["o_-","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#o_-2d","Rotate: shift the items round by n (APL's rotate); positive n moves items toward the front."],
["o_\\","built-in","a -> a","a -> a","","builtins.html#o_-5c","Transpose: reverse the order of the axes, so a matrix's rows become its columns; a vector or a single value is unchanged."],
["t_ranspose","built-in","Int -> a -> a","Int -> a -> a","","builtins.html#t_ranspose","Permute the axes: the left argument lists each axis once, and axis i of the right argument becomes the axis that item i of the list names (APL's dyadic transpose), so `3 1 2` moves axis 1 to the end."]
